fn main() {
    let a: f32 = 42.42;

    let bits: u32 = a.to_bits();
    println!("{}", bits);
    println!("{:032b}", bits);

    let b = f32::from_bits(bits);
    println!("{}", b);

    // what transmute does, for comparison
    let same: u32 = unsafe { std::mem::transmute(a) };
    println!("{}", same == bits);
}

fn main() {
    let x: u8 = 250;

    println!("{:?}", x.checked_add(10));     // None on overflow
    println!("{}", x.wrapping_add(10));      // wraps modulo 256
    println!("{}", x.saturating_add(10));    // stops at the maximum
    println!("{:?}", x.overflowing_add(10)); // wrapped value and a flag

    println!("{}", (-5i8) as u8);
    println!("{}", 300i32 as u8);
    println!("{}", i8::MIN.wrapping_abs());
    println!("{:?}", i8::MIN.checked_abs());
}

fn main() {
    let flags: u8 = 0b0000_0000;
    let read = 1 << 0;
    let write = 1 << 1;
    let exec = 1 << 2;

    let perms = flags | read | write;
    println!("{perms:08b} can write: {}", perms & write != 0);
    println!("{:08b} after removing write", perms & !write);
    println!("{:08b} toggled exec", perms ^ exec);

    let color: u32 = 0x00FF_8800;
    let (r, g, b) = ((color >> 16) & 0xFF, (color >> 8) & 0xFF, color & 0xFF);
    println!("r={r} g={g} b={b}");

    println!("{} {} {}", 0b1011u8.count_ones(), 1u32.leading_zeros(), -16i32 >> 2);
}

